import{_ as e,p,q as s,s as t,R as o,t as r,Y as d,n}from"./framework-e1bed10d.js";const c="/my-blog/assets/018_01-f843536f.png",i="/my-blog/assets/018_02-694c5974.png",u="/my-blog/assets/018_03-3cabdf23.png",I="/my-blog/assets/018_04-ec789f27.png",h="/my-blog/assets/018_05-b5a5c800.png",A="/my-blog/assets/018_06-5f0becce.png",_="/my-blog/assets/018_07-2ead3300.png",q={},l=t("h1",{id:"ai-时代的流程重塑",tabindex:"-1"},[t("a",{class:"header-anchor",href:"#ai-时代的流程重塑","aria-hidden":"true"},"#"),o(" AI 时代的流程重塑")],-1),m={href:"https://mp.weixin.qq.com/s?__biz=MzIzNzQ5NjU5NQ==&mid=2247484541&idx=1&sn=5cabe788f51f1d343301ad2725bba83d&chksm=e8c6f401dfb17d17c66f081ab7c9a07d939b634781a7009ded3f5e72a59efe785fc93f294396",target:"_blank",rel:"noopener noreferrer"},g=d('<hr><p>八、<strong>AI 时代的流程重塑</strong></p><p><img src="'+c+'" alt="图片"></p><p>图2-41 AI时代信贷流程重塑：传统流程vs智能流程</p><p>本章前半部分讲的，是过去二十年信贷系统长出来的样子：人工审批、规则引擎、评分卡、批量催收。而此刻正在发生的，是AI 对这条流程的重塑。我亲历了银行信息化到互联网金融、再到 AI 金融的演进，可以负责任地说：AI 没有改变信贷业务的本质，但它在改变流程的效率、形态和边界。这一节不预测未来，只讲已经在落地的事情。</p><h3 id="一-ai-核身-进件流程的简化" tabindex="-1"><a class="header-anchor" href="#一-ai-核身-进件流程的简化" aria-hidden="true">#</a> （一）AI 核身：进件流程的简化</h3><p><img src="'+i+'" alt="图片"></p><p>图2-42 AI核身前后进件流程对比</p><p>AI 核身是金融科技最早成熟的 AI 应用之一。人脸识别、活体检测、证件识别，让远程开户、远程进件成为可能。没有 AI 核身，线上贷款的第一步&quot;确认是你本人&quot;就无法完成，必须到线下网点。有了 AI 核身，客户在 App 上刷脸 + 读身份证 + 活体检测，几分钟完成身份验证，进件流程大为简化。</p><p>AI 核身对流程重塑的意义，不只是省掉一趟网点，而是让整个线上信贷链路闭环：身份可信了，电子签约才能生效，远程放款才敢做。我在互金平台做消费金融时，AI 核身是线上进件的第一道闸，核身不过，后面的反欺诈、准入、审批都不会启动。因为无法确认&quot;借款的是不是本人&quot;，一切风险判断都没有意义。核身的技术细节（人脸比对、活体检测、防攻击）已经很成熟，对产品经理和工程师来说，更重要的是理解核身在流程中的位置：它是线上信贷&quot;信任链&quot;的起点。</p><h3 id="二-ai-客服与智能外呼-嵌入全流程" tabindex="-1"><a class="header-anchor" href="#二-ai-客服与智能外呼-嵌入全流程" aria-hidden="true">#</a> （二）AI 客服与智能外呼：嵌入全流程</h3><p><img src="'+u+'" alt="图片"></p><p>图2-43 AI客服与智能外呼在信贷全流程的嵌入位置</p><p>AI 客服和智能外呼是 AI 渗透最自然的场景，因为它们不改变业务规则，只改变交互方式。贷前咨询阶段，智能客服解答产品问题、引导进件；贷中确认阶段，智能外呼确认借款意愿、核对身份信息、确认放款事宜；贷后阶段，智能外呼做还款提醒、逾期通知、催收初筛。信贷系统里已经有&quot;智能外呼&quot;这个贷后服务，说明这不是概念，而是已经进入生产系统的能力。</p><p>智能外呼的价值，在于把高重复、低价值的人工作业替换掉。催收团队最费人力的是外呼初筛。打几百通电话，大部分是无效号码和无人接听。智能外呼先做初筛，把接通、有意愿的客户转人工，把无效电话过滤掉，催收员的时间全部花在真正需要人的案件上。我在民营银行做催收系统时，智能外呼上线后，催收员人均有效作业量提升了一倍多，而且接通率、首呼回收率都有明显改善。</p><p>AI 客服和智能外呼还有一层隐性价值：它们产生的大量对话数据，是后续 AI 模型训练的原料。客户的常见问题、投诉焦点、催收中客户的真实反馈，都沉淀在对话记录里，可以被用来优化产品、优化话术、优化风险评估。流程重塑不是一次性工程，而是数据驱动的持续迭代。</p><h3 id="三-智能审批-从-人看-到-人机协作-再到-全自动" tabindex="-1"><a class="header-anchor" href="#三-智能审批-从-人看-到-人机协作-再到-全自动" aria-hidden="true">#</a> （三）智能审批：从“人看”到“人机协作”再到“全自动”</h3><p><img src="'+I+'" alt="图片"></p><p>图2-44智能审批三阶段演进：人工→人机协作→全自动</p><p>审批是AI 介入最深、收益最明显的环节。传统审批是人看材料，客户经理调查、审查岗审查、审批人决策，一笔对公贷款走完流程要几周。互联网信贷时代，审批已经部分自动化，但规则还是人工写的规则引擎。AI 时代的变化在于，审批从&quot;人写规则&quot;走向&quot;模型学习规则&quot;。</p><p>现实的落地路径不是一步到位的，而是分阶段演进。第一阶段是模型初审+ 人复核：系统通过 OCR 和结构化抽取自动读取进件材料、给出审批建议和风险提示，人工在 AI 建议的基础上复核决策。第二阶段是条件化全自动审批：在金额小、客群标准、模型稳定的产品上，AI 审批结果直接生效，人工只做抽检和异常处理。我在民营银行推线上小微贷时，就是从&quot;模型初审 + 人复核&quot;起步，跑了大半年，验证到位才逐步放开全自动审批的比例。</p><p>智能审批要落地，有一个前提：进件材料的数字化。AI 读不了纸面材料，它读的是结构化的进件数据、影像识别的结果、第三方数据。所以智能审批不是孤立地换一个决策模型，而是反过来推动进件、尽调、数据采集的数字化。这也是为什么我在第一节讲进件时强调渠道适配和数据建模。没有干净的进件数据，AI 审批就是空中楼阁。</p><p>AI重塑流程，最后一定会落到组织变化上。传统信贷部门是金字塔结构：大量基层审批员、录入员、催收员做重复活，越往上人越少；AI上线后，这些重复性的岗位会大幅收缩——原来一个审批岗一天审几十笔，现在AI初审完，审批员一天要复核几百笔；原来催收团队一半人打无效电话，现在智能外呼干完了初筛，催收员只处理真正有还款意愿的案件。对应的，团队里会新增模型运营、数据治理、AI策略产品这些新角色，从&quot;堆人堆流程&quot;变成&quot;人盯模型、处理异常case&quot;。做系统的人要知道，你上线一个AI能力，不是只交一个模型接口，后面跟着的是整个团队的工作方式变了。</p><h3 id="四-自动尽调-ai-生成尽调报告与财报分析" tabindex="-1"><a class="header-anchor" href="#四-自动尽调-ai-生成尽调报告与财报分析" aria-hidden="true">#</a> （四）自动尽调：AI 生成尽调报告与财报分析</h3><p><img src="'+h+'" alt="图片"></p><p>图2-45 AI自动尽调流程：从多源数据到结构化报告</p><p>尽调是信贷流程里最&quot;重&quot;的环节，对公业务更是这样，信贷员要上门调查、收集财报、分析经营状况、撰写尽调报告。AI 正在把这个环节自动化。自动尽调的方向有两块：一是数据采集自动化，通过开放接口自动获取工商、税务、司法、征信、财报等数据，替代人工收集。报告生成则走向智能化，AI 基于采集的数据自动生成尽调报告初稿，包含经营分析、财务指标、风险提示，信贷员在初稿基础上补充现场调查信息、修正判断。</p><p>我在产业金融做供应链金融时，尽调对象是链上的小微企业，数量大、金额小、单笔尽调成本承受不了传统模式。自动尽调让这个矛盾有了解法：系统自动拉取企业的发票数据、物流数据、结算数据，系统基于规则和模型自动生成经营画像和授信建议，信贷员只对高风险或大金额的客户做现场尽调。尽调从&quot;逐户人工&quot;变成了&quot;系统初筛 + 人工复核&quot;，作业效率和覆盖面不在一个量级上。</p><p>自动尽调要守住一条底线：AI 生成的报告只能作为辅助判断，不能替代人的法律和合规责任。尽调报告涉及客户隐私、商业秘密、证据效力，AI 生成的报告必须有人的确认环节，报告底稿、数据来源、模型版本都要留痕，出了问题能追溯到责任。这既是对客户负责，也是给 AI 自己留退路。</p><h3 id="五-ai-时代-状态机与风控的再思考" tabindex="-1"><a class="header-anchor" href="#五-ai-时代-状态机与风控的再思考" aria-hidden="true">#</a> （五）AI 时代：状态机与风控的再思考</h3><p><img src="'+A+'" alt="图片"></p><p>图2-46 AI时代状态机与风控的再思考：传统vs智能</p><p>AI 重塑了流程，但有一点没变：AI 的判断也要落回到信贷的状态机上。AI 审批给出的是&quot;是否通过、授信多少&quot;，这个结论最终要翻译成额度状态机里的一次&quot;额度生效&quot;、借据状态机里的一次&quot;待放款&quot;。AI 外呼识别的还款意愿，最终要翻译成催收策略的一次调整。所以对系统工程师来说，AI 落地不是一个&quot;换模型&quot;的问题，而是一个&quot;模型输出如何对接状态机&quot;的工程问题。模型的输出要标准化成业务事件，事件再驱动状态迁移，这条链路不会因为 AI 而改变。</p><p>另一个值得思考的落点是风险预警。AI 对贷后监控的增强，主要体现在&quot;更早发现&quot;：传统的贷后检查是定期人工看，AI 可以实时扫描客户的资金流、经营数据、社交信号，提前给出风险预警，驱动风险分类提前调整。信贷系统里的风险预警、贷中监控、还款预测，就是为这个方向准备的。还款预测这个能力很有意思：基于客户的历史行为预测下期会不会逾期，预测结果可以驱动提前催收、提前调整授信，把贷后的&quot;事后处置&quot;变成&quot;事中干预&quot;。</p><p>把AI 的几块落地放在一起看，能得出一个共同的结论：AI 改变了流程的效率和形态，但没有改变流程的骨架。智能审批的结论要落到额度状态机和借据状态机上，AI 外呼的识别结果要落到催收策略上，自动尽调的报告要落到评级和授信参数上，它们最终都要通过确定性的状态迁移来生效。</p><p>智能体（Agent）的兴起，给流程重塑带来了新的可能性。贷前、贷中、贷后各环节都有适合智能体的场景，但边界各不相同：</p><table><thead><tr><th><strong>流程环节</strong></th><th><strong>智能体应用</strong></th><th><strong>边界</strong></th></tr></thead><tbody><tr><td>贷前</td><td>智能咨询助手、自动尽调助手</td><td>辅助，最终审批人工</td></tr><tr><td>贷中</td><td>智能监控助手、风险预警助手</td><td>预警，处置人工</td></tr><tr><td>贷后</td><td>智能催收助手、智能客服</td><td>话术合规审核，特殊案件人工</td></tr></tbody></table><p>表2-7智能体在信贷各环节的落地边界</p><p><img src="'+_+'" alt="图片"></p><p>图2-47智能体在信贷各环节的落地边界：成熟/探索/必须人在环路</p>',40);function b(f,x){const a=n("ExternalLinkIcon");return p(),s("div",null,[l,t("blockquote",null,[t("p",null,[o("公众号：侃西东　·　发布日期：2026-09-30　·　"),t("a",m,[o("微信原文"),r(a)])])]),g])}const k=e(q,[["render",b],["__file","018.html.vue"]]);export{k as default};
